      ro: ["Aproape de faimoasa Pădure a Copacilor Quiver.", "Prezintă clădiri din era colonială germană."],
      en: ["Close to the famous Quiver Tree Forest.", "Features buildings from the German colonial era."],
      es: ["Cerca del famoso Bosque de Árboles de Carcaj.", "Cuenta con edificios de la época colonial alemana."],
      pt: ["Perto da famosa Floresta de Árvores de Aljava.", "Possui edifícios do período colonial alemão."],
