      hu: ["Magában foglalja az oshikangói határállomást.", "Az Angolába irányuló áruk exportjának fő központja."],
      ro: ["Incorporează postul de frontieră Oshikango.", "Un hub major pentru exportul de mărfuri în Angola."],
      en: ["Incorporates the border post of Oshikango.", "A major hub for exporting goods to Angola."],
      es: ["Incluye el puesto fronterizo de Oshikango.", "Un nudo importante para la exportación de mercancías hacia Angola."],
