      ro: ["Bukalo a fost proclamat oficial sat în anul 2013.", "Localitatea este sediul Masubia Khuta (tribunalul tradițional).", "Bukalo se află pe drumul principal M136, care duce spre granița Ngoma.", "Festivalul cultural anual Bunya are loc de obicei în iulie sau august.", "Râul Chobe curge la o distanță relativ mică la sud de sat.", "Kuniho Kisco Liswani III este actualul șef al poporului Masubia din Bukalo."],
      en: ["Bukalo was officially proclaimed a village in 2013.", "The settlement serves as the headquarters of the Masubia Khuta (Traditional Court).", "Bukalo is located along the M136 road leading to the Ngoma border post.", "The annual Bunya cultural festival is typically celebrated in July or August.", "The Chobe River flows in relatively close proximity to the south of the village.", "Kuniho Kisco Liswani III is the reigning chief of the Masubia people in Bukalo."],
